// Exportar para uso em módulos
if (typeof module !== 'undefined' && module.exports) {
    module.exports = dataPositions;
}

// Função para filtrar por categoria
function getPositionsByCategory(category) {
    return dataPositions.filter(pos => pos.category === category);
}

// Função para buscar por nome
function searchPositions(query) {
    const lowerQuery = query.toLowerCase();
    return dataPositions.filter(pos => 
        pos.name.toLowerCase().includes(lowerQuery) ||
        pos.category.toLowerCase().includes(lowerQuery) ||
        (pos.description && pos.description.toLowerCase().includes(lowerQuery))
    );
}

// Função para obter todas as categorias únicas
function getAllCategories() {
    return [...new Set(dataPositions.map(pos => pos.category))].sort();
}

// Estatísticas
const stats = {
    total: dataPositions.length,
    categories: getAllCategories(),
    byCategory: {}
};

stats.categories.forEach(cat => {
    stats.byCategory[cat] = dataPositions.filter(pos => pos.category === cat).length;
});

console.log('Data Positions loaded:', stats.total);
console.log('Categories:', stats.categories.length);

// Exportar funções auxiliares
if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        positions: dataPositions,
        getPositionsByCategory,
        searchPositions,
        getAllCategories,
        stats
    };
}
